#define RL_POLICY_OBS_SIZE 18
#define RL_POLICY_ACTION_SIZE 5
/* Move-target/cast-flag bounds -- must match scripts/rl_env.py's own
 * MOVE_TARGET_RANGE and action_space definition exactly. PPO's own action_net
 * is a plain unconstrained Linear layer (no output activation), so the raw
 * forward pass alone does not guarantee in-range values -- this wrapper clips.
 */
#define RL_POLICY_MOVE_TARGET_RANGE 20.0f

/* rl_policy_forward: runs the policy network and clips the raw action-mean
 * output to the real action-space bounds -- out_action must be preallocated
 * to RL_POLICY_ACTION_SIZE floats. */
static inline void rl_policy_forward(const float *obs, float *out_action) {
    mlp_forward(&RL_POLICY_MODEL, obs, out_action);
    if (out_action[0] < -RL_POLICY_MOVE_TARGET_RANGE) out_action[0] = -RL_POLICY_MOVE_TARGET_RANGE;
    if (out_action[0] >  RL_POLICY_MOVE_TARGET_RANGE) out_action[0] =  RL_POLICY_MOVE_TARGET_RANGE;
    if (out_action[1] < -RL_POLICY_MOVE_TARGET_RANGE) out_action[1] = -RL_POLICY_MOVE_TARGET_RANGE;
    if (out_action[1] >  RL_POLICY_MOVE_TARGET_RANGE) out_action[1] =  RL_POLICY_MOVE_TARGET_RANGE;
    for (int i = 2; i < RL_POLICY_ACTION_SIZE; i++) {
        if (out_action[i] < -1.0f) out_action[i] = -1.0f;
        if (out_action[i] >  1.0f) out_action[i] =  1.0f;
    }
}

